    const Y=(th)=>N*assocLeg(l,m,Math.cos(th));let mx=0;for(let i=0;i<=400;i++)mx=Math.max(mx,Math.abs(Y(i/400*Math.PI)));mx=mx||1;
    const lw=Math.min(h,Math.floor(w*0.4)),cx=lw/2,cy=h/2,R=lw/2-14;
    ctx.save();ctx.strokeStyle=K.gr;ctx.beginPath();ctx.arc(cx,cy,R,0,TAU);ctx.stroke();ctx.strokeStyle=K.ax;ctx.beginPath();ctx.moveTo(cx,cy-R-8);ctx.lineTo(cx,cy+R+8);ctx.moveTo(cx-R-8,cy);ctx.lineTo(cx+R+8,cy);ctx.stroke();ctx.restore();
    label(ctx,'z',cx+6,cy-R-4,K.mut);label(ctx,'x',cx+R+2,cy-8,K.mut);
    [[1,1],[-1,m%2?-1:1]].forEach(([side,sg])=>{for(let i=0;i<360;i++){const t0=i/360*Math.PI,t1=(i+1)/360*Math.PI,v0=sg*Y(t0)/mx,v1=sg*Y(t1)/mx;
      ctx.beginPath();ctx.moveTo(cx+side*Math.abs(v0)*R*Math.sin(t0),cy-Math.abs(v0)*R*Math.cos(t0));ctx.lineTo(cx+side*Math.abs(v1)*R*Math.sin(t1),cy-Math.abs(v1)*R*Math.cos(t1));ctx.strokeStyle=(v0+v1)>=0?K.b:K.a;ctx.lineWidth=2.6;ctx.stroke();}});
    const x0=lw+40,mw=w-x0-10,mh=Math.min(h-30,mw/2);
    heat(ctx,x0,10,mw,mh,(u,v)=>{const th=v*Math.PI,ph=u*TAU;return Y(th)*Math.cos(m*ph)/mx;},2);
