    if(+sv.value===2){ctx.save();ctx.fillStyle='rgba(201,42,42,.08)';ctx.fillRect(A.X(Math.PI/3),A.o.t,A.X(2*Math.PI/3)-A.X(Math.PI/3),A.o.h);ctx.restore();}
    if(+sv.value===1)curve(ctx,A,x=>6*x/40,0,Math.PI,'rgba(201,42,42,.4)',1.5,[4,4]);
    path(ctx,A,S.o.map(p=>[p[0],p[1]/S.mx]),K.t,2.8);dot(ctx,A.X(Math.PI),A.Y(S.end),6,Math.abs(S.end)<0.02?K.r:K.w);
