    const P=cplane(ctx,lw,h,2.2,0,lw),D=g*g-1,hp=D<0?[[-g,Math.sqrt(-D)],[-g,-Math.sqrt(-D)]]:[[-g+Math.sqrt(D),0],[-g-Math.sqrt(D),0]];
