    ctx.save();ctx.fillStyle='rgba(112,72,232,.25)';ctx.beginPath();ctx.moveTo(A.X(0),A.Y(0));for(let i=0;i<=400;i++){const tau=i/400*10;ctx.lineTo(A.X(tau),A.Y(f(tau)*g(t-tau)));}ctx.lineTo(A.X(10),A.Y(0));ctx.fill();ctx.restore();
