    ctx.save();ctx.strokeStyle=K.f;ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(A.X(t),A.o.t);ctx.lineTo(A.X(t),A.o.t+A.o.h);ctx.stroke();ctx.restore();label(ctx,'τ = t',A.X(t)+4,A.o.t+10,K.f);
    const pts=[];for(let i=0;i<=200;i++){const s=i/200*10;pts.push([s,conv(f,g,s)]);}const ym=Math.max(...pts.map(p=>Math.abs(p[1])))*1.2||1;
