    rd2.innerHTML=row('f',nf1)+row('g',ng)+row('t',nf(t,2))+row('(f * g)(t) = ∫₀ᵗ f(τ) g(t − τ) dτ',nt(v,4))+sep+
      rowT(sp.value==='rr'?'Dos pulsos de ancho 2 dan un triángulo de base 4: el área de solapamiento crece y luego decrece linealmente.':sp.value==='er'?'Un filtro RC (respuesta e⁻ᵗ) excitado por un pulso: carga mientras dura el pulso y luego descarga.':'Respuesta del oscilador a un pulso: es la convolución de la fuerza con la función de Green.')+
      rowT('En Laplace: 𝓛{f * g} = F(s)·G(s).')+leg([[K.t,'f(τ)'],[K.b,'g(t − τ)'],['rgba(112,72,232,.5)','producto']]);
