    curve(ctx,A,x=>{let s=0;for(let n=1;n<=N;n++)s+=B[n]*Math.sin(n*Math.PI*x)*Math.cos(n*Math.PI*t);return s;},0,1,K.b,3,null,600);
    const Bx=axes(ctx,{l:36,t:h1+4,w:w-46,h:h-h1-28,xr:[0,Math.max(N,10)+1],yr:[0,1.1],xl:'n',yl:'|bₙ|',xf:v=>nt(v,0)});const bm=Math.max(...B.slice(1).map(Math.abs))||1;
    for(let n=1;n<=N;n++){ctx.save();ctx.strokeStyle=K.t;ctx.lineWidth=Math.max(2,Math.min(10,(Bx.X(1)-Bx.X(0))*0.6));ctx.beginPath();ctx.moveTo(Bx.X(n),Bx.Y(0));ctx.lineTo(Bx.X(n),Bx.Y(Math.abs(B[n])/bm));ctx.stroke();ctx.restore();}
    const E=B.slice(1,N+1).reduce((s,b,i)=>s+((i+1)*b)**2,0),E3=B.slice(1,Math.min(N,3)+1).reduce((s,b,i)=>s+((i+1)*b)**2,0);
